design.css:
/* Flat navigation, quiet tabs, and typography-led note content. */
:scope { --tigrana-panel-gap: 6px; --tigrana-workspace-inset: 0px; --tigrana-panel-radius: 0px; }
.app-titlebar { background: var(--tigrana-surface); border-bottom: 1px solid var(--tigrana-border); }
.note-tab { border-radius: 8px; background: transparent; }
.app-titlebar .note-tab.is-active { background: var(--surface-strong); color: var(--tigrana-text); border: 0; box-shadow: none; }
:scope.theme-light .note-tab.is-active { background: var(--surface-muted); }
.pane-header { color: var(--tigrana-muted); font-size: 12px; font-weight: 500; border-bottom: 0; }
.topbar { background: transparent; border-bottom: 0; }
.section-view-folder-pane .folder-row { border-radius: 0; }
.title-shell { border-bottom: 1px solid var(--tigrana-border); }
.note-title-input { font-weight: 700; letter-spacing: -0.025em; }
.ProseMirror h1, .ProseMirror h2, .ProseMirror h3 { font-weight: 600; letter-spacing: -0.02em; }
.ProseMirror blockquote { background: transparent; border-radius: 0; border-left: 2px solid var(--tigrana-border); padding-left: 18px; }
.ProseMirror pre { background: var(--surface-soft); border: 0; border-radius: 3px; }
/* Keep the left shadow above the editor scroll fades. */
.pane-resizer--left-of-main { z-index: 13; }
:scope { --tigrana-sidebar-edge-shadow: rgba(0, 0, 0, 0.10); }
:scope.theme-dark { --tigrana-sidebar-edge-shadow: rgba(0, 0, 0, 0.24); }
.pane-resizer--left-of-main::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  width: 10px;
  pointer-events: none;
}
.pane-resizer--left-of-main::before {
  left: 100%;
  background: linear-gradient(to right, var(--tigrana-sidebar-edge-shadow), transparent);
}
.pane-resizer--left-of-main::after, .pane-resizer--right-of-main::after { background: transparent; }
.pane-resizer--left-of-main:hover::after, .pane-resizer--right-of-main:hover::after { background: var(--tigrana-accent); }
/* A nearly opaque color avoids WebKit making fully opaque selections translucent. */
.ProseMirror::selection, .ProseMirror *::selection, .note-title-input::selection, .raw-markdown-input::selection { background-color: color-mix(in srgb, var(--tigrana-accent) 99.9%, transparent); color: var(--tigrana-selected-text); }
/* Leave list markers unhighlighted; paragraph and inline text keep their selection colors. */
.ProseMirror li::selection { background-color: transparent; color: inherit; }
